import{_ as u,a0 as a,w as l,s as i,ao as s,I as n,x as e,a1 as p,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在Linux中使用awk命令 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux中使用awk命令 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux中使用awk命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux中使用awk命令 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140729 How to use awk command in Linux","title":"如何在Linux中使用awk命令","tag":"201410","desc":""},"relativePath":"201410/20140729 How to use awk command in Linux.md","filePath":"[post].md"}'),k={name:"201410/20140729 How to use awk command in Linux.md"};function d(w,o,m,q,f,T){const t=a("Link");return l(),i("div",null,[o[18]||(o[18]=s(`<h1 id="如何在linux中使用awk命令" tabindex="-1">如何在Linux中使用awk命令 <a class="header-anchor" href="#如何在linux中使用awk命令" aria-label="Permalink to “如何在Linux中使用awk命令”">​</a></h1><p>文本处理是Unix的核心。从管道到/proc子系统，“一切都是文件”的理念贯穿于操作系统和所有基于它构造的工具。正因为如此，轻松地处理文本是一个期望成为Linux系统管理员甚至是资深用户的最重要的技能之一，而 awk是通用编程语言之外最强大的文本处理工具之一。</p><p>最简单的awk的任务是从标准输入中选择字段；如果你对awk除了这个用途之外，从来没了解过它的其他用途，你会发现它还是会是你身边一个非常有用的工具。</p><p>默认情况下，awk通过空格分隔输入。如果您想选择输入的第一个字段，你只需要告诉awk输出$ 1：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $1}&#39;
</code></pre><blockquote><p>one</p></blockquote><p>（是的，大括号语法是有点古怪，但我保证这是我们这节课一直会遇到。）</p><p>你能猜出如何选择第二，第三或第四个字段么？是的，分别用$2，$ 3，$ 4。</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $3}&#39;
</code></pre><blockquote><p>three</p></blockquote><p>通常在文本改写时，你需要创建一个特定的数据格式，并且它覆盖不止一个单词。好消息是，awk中可以很容易地打印多个字段，甚至包含静态字符串：</p><pre><code> $ echo &#39;one two three four&#39; | awk &#39;{print $3,$1}&#39; 
</code></pre><blockquote><p>three one</p></blockquote><hr><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print &quot;foo:&quot;,$3,&quot;| bar:&quot;,$1}&#39; 
</code></pre><blockquote><p>foo: three | bar: one</p></blockquote><p>好吧，如果你的输入不是由空格分隔怎么办？只需用awk中的&#39;-F&#39;标志指定你的分隔符：</p><pre><code>$ echo &#39;one mississippi,two mississippi,three mississippi,four mississippi&#39; | awk -F , &#39;{print $4}&#39; 
</code></pre><blockquote><p>four mississippi</p></blockquote><p>偶尔间，你会发现自己正在处理字段数量不同的数据，但你只知道你想要的<em>最后</em>字段。 awk中内置的$NF变量代表<em>字段的数量</em>，这样你就可以用它来抓取最后一个元素：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $NF}&#39; 
</code></pre><blockquote><p>four</p></blockquote><p>你也可以用$NF做简单的数学，假如你需要倒数第二个字段：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $(NF-1)}&#39; 
</code></pre><blockquote><p>three</p></blockquote><p>甚至是中间的字段：</p><pre><code>$ echo &#39;one two three four&#39; | awk &#39;{print $((NF/2)+1)}&#39; 
</code></pre><blockquote><p>three</p></blockquote><p>而且这一切都非常有用，同样你可以摆脱强制使用sed，cut，和grep来得到这些结果（尽管要做更多的操作）。</p><p>因此，我将最后为你介绍awk的一个特性，维持跨行状态。</p><pre><code> $ echo -e &#39;one 1\\ntwo 2&#39; | awk &#39;{print $2}&#39; 
</code></pre><blockquote><p>1</p><p>2</p></blockquote><pre><code>$ echo -e &#39;one 1\\ntwo 2&#39; | awk &#39;{sum+=$2} END {print sum}&#39; 
</code></pre><blockquote><p>3</p></blockquote><p>（END代表的是我们在执行完每行的处理<strong>之后</strong>只处理下面的代码块）</p><p>这里我使用的例子是统计web服务器请求日志的字节大小。想象一下我们有如下这样的日志：</p><pre><code>$ cat requests.log 
</code></pre><blockquote><p>Jul 23 18:57:12 httpd[31950]: &quot;GET /foo/bar HTTP/1.1&quot; 200 344</p><p>Jul 23 18:57:13 httpd[31950]: &quot;GET / HTTP/1.1&quot; 200 9300</p><p>Jul 23 19:01:27 httpd[31950]: &quot;GET / HTTP/1.1&quot; 200 9300</p><p>Jul 23 19:01:55 httpd[31950]: &quot;GET /foo/baz HTTP/1.1&quot; 200 6401</p><p>Jul 23 19:02:31 httpd[31950]: &quot;GET /foo/baz?page=2 HTTP/1.1&quot; 200 6312</p></blockquote><p>我们知道最后一个字段是响应的字节大小。我们已经学习了如何使用$NF来抽取他们：</p><pre><code>$ &lt; requests.log awk &#39;{print $NF}&#39; 
</code></pre><blockquote><p>344</p><p>9300</p><p>9300</p><p>6401</p><p>6312</p></blockquote><p>接着我们可以将它们累加到一个变量中来收集我们的web服务其在日志中这段时间内的响应客户端的字节数量</p><pre><code>$ &lt; requests.log awk &#39;{totalBytes+=$NF} END {print totalBytes}&#39; 
</code></pre><blockquote><p>31657</p></blockquote>`,44)),n("p",null,[o[2]||(o[2]=e("如果你正在寻找关于awk的更多资料，你可以在Amazon中花费不到15美元买到",-1)),p(t,{href:"http://www.amazon.com/gp/product/020107981X/ref=as_li_tl?ie=UTF8&camp=1789&creative=9325&creativeASIN=020107981X&linkCode=as2&tag=xmodulo-20&linkId=6NW62B2WBRBXRFJB"},{default:r(()=>[...o[0]||(o[0]=[e("原始awk手册",-1)])]),_:1}),o[3]||(o[3]=e("的二手书。你也许还可以看看Eric Pement的",-1)),p(t,{href:"http://www.pement.org/awk/awk1line.txt"},{default:r(()=>[...o[1]||(o[1]=[e("单行awk命令收集",-1)])]),_:1}),o[4]||(o[4]=e("这本书。",-1))]),o[19]||(o[19]=n("hr",null,null,-1)),n("p",null,[o[6]||(o[6]=e("via: ",-1)),p(t,{href:"http://xmodulo.com/2014/07/use-awk-command-linux.html"},{default:r(()=>[...o[5]||(o[5]=[e("http://xmodulo.com/2014/07/use-awk-command-linux.html",-1)])]),_:1})]),n("p",null,[o[10]||(o[10]=e("作者：",-1)),p(t,{href:"http://xmodulo.com/author/james"},{default:r(()=>[...o[7]||(o[7]=[e("James Pearson",-1)])]),_:1}),o[11]||(o[11]=e(" 译者：",-1)),p(t,{href:"https://github.com/geekpi"},{default:r(()=>[...o[8]||(o[8]=[e("geekpi",-1)])]),_:1}),o[12]||(o[12]=e(" 校对：",-1)),p(t,{href:"https://github.com/wxy"},{default:r(()=>[...o[9]||(o[9]=[e("wxy",-1)])]),_:1})]),n("p",null,[o[15]||(o[15]=e("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[13]||(o[13]=[e("LCTT",-1)])]),_:1}),o[16]||(o[16]=e(" 原创翻译，",-1)),p(t,{href:"http://linux.cn/"},{default:r(()=>[...o[14]||(o[14]=[e("Linux中国",-1)])]),_:1}),o[17]||(o[17]=e(" 荣誉推出",-1))])])}const c=u(k,[["render",d]]);export{x as __pageData,c as default};
